/**
 * Host-aware site icons. The Circle Hub and Athena share one deployment, so
 * /favicon.ico, /favicon.svg, /apple-touch-icon.png and /site.webmanifest are
 * served here instead of from public/: Athena hosts (meetathena.io and its
 * subdomains) get the Athena logo, every other host keeps the Circle icons
 * byte-for-byte as they were. Text-only tooling cannot commit binaries, so
 * the bytes live here as base64.
 */

type Asset = { type: string; body: string; base64: boolean };

