/** Circle PWA icons named in the Circle manifest; served on every host (the public/brand/circle-v1 PNGs were overwritten). */
const CIRCLE_BRAND: Record<string, Asset> = {
  "/brand/circle/app-icon-256.png": { type: "image/png", base64: true, body: "" },
  "/brand/circle/app-icon-512.png": { type: "image/png", base64: true, body: "" },
  "/brand/circle/favicon-32.png": { type: "image/png", base64: true, body: "" },
};

/** 0.8.10: CORS headers on every Athena connector icon PNG, on both domains. */
export const ICON_CORS = Object.freeze({
  "access-control-allow-origin": "*",
  "access-control-allow-methods": "GET, HEAD, OPTIONS",
  "cross-origin-resource-policy": "cross-origin",
  "timing-allow-origin": "*",
}) as Record<string, string>;

export function isAthenaHost(hostname: string): boolean {
  const h = hostname.toLowerCase();
  return h === "meetathena.io" || h.endsWith(".meetathena.io");
}

function decode(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

/** Returns the icon response for GET/HEAD of a site-icon path, else null. */
export function siteIconResponse(request: Request): Response | null {
  const method = request.method.toUpperCase();
  const url = new URL(request.url);
  // 0.8.10: CORS preflight on the connector icon PNGs (was a 404).
  if (method === "OPTIONS" && ATHENA_BRAND[url.pathname]) {
    return new Response(null, { status: 204, headers: { ...ICON_CORS, "access-control-max-age": "86400" } });
  }
  if (method !== "GET" && method !== "HEAD") return null;
  const set = isAthenaHost(url.hostname) ? ATHENA : CIRCLE;
  const brand = ATHENA_BRAND[url.pathname];
  const asset = brand ?? CIRCLE_BRAND[url.pathname] ?? set[url.pathname];
  if (!asset) return null;
  const body = asset.base64 ? decode(asset.body) : asset.body;
  return new Response(method === "HEAD" ? null : (body as BodyInit), {
    status: 200,
    headers: {
      "content-type": asset.type,
      "cache-control": "public, max-age=3600",
      vary: "Host",
      // Connector icons are fetched cross-origin by ChatGPT and Claude. Circle icon headers are unchanged.
      ...(brand ? ICON_CORS : {}),
    },
  });
}
